package secretbox

import "testing"

// legacyVector was generated by the webhook encrypt function at HEAD dc7c077
// (before this change) with key "01234567890123456789012345678901" and
// plaintext "whsec_legacy_vector". It pins the stored format, not a fixed
// external fixture.
const legacyVector = "vZ0aT4qGSmpN2jwdqekfi9Rdq9OaCfzS5fs2Pihg0nio7gte0L1L/t8sL6GPIPQ"

var legacyKey = []byte("01234567890123456789012345678901")

func TestOpenDecryptsLegacyWebhookCiphertext(t *testing.T) {
	box := New(map[int][]byte{1: legacyKey}, 1)
	plain, err := box.Open(1, legacyVector)
	if err != nil || plain != "whsec_legacy_vector" {
		t.Fatalf("Open legacy = %q, %v", plain, err)
	}
}

func TestSealUsesPrimaryVersionAndRoundTrips(t *testing.T) {
	box := New(map[int][]byte{1: legacyKey, 2: []byte("abcdefghijklmnopqrstuvwxyz012345")}, 2)
	sealed, version, err := box.Seal("whsec_new")
	if err != nil || version != 2 {
		t.Fatalf("Seal version = %d, err = %v", version, err)
	}
	if plain, err := box.Open(version, sealed); err != nil || plain != "whsec_new" {
		t.Fatalf("Open sealed = %q, %v", plain, err)
	}
	// A row sealed under the primary key must not open under the fallback key.
	if _, err := New(map[int][]byte{1: legacyKey}, 1).Open(1, sealed); err == nil {
		t.Fatal("ciphertext opened with the wrong key")
	}
}

func TestOpenFailsForUnknownVersion(t *testing.T) {
	box := New(map[int][]byte{2: legacyKey}, 2)
	if _, err := box.Open(1, legacyVector); err == nil {
		t.Fatal("expected error for a version with no configured key")
	}
}

func TestConfiguredRequiresPrimaryKey(t *testing.T) {
	if New(nil, 0).Configured() {
		t.Fatal("empty keyring reported configured")
	}
	if New(map[int][]byte{1: legacyKey}, 2).Configured() {
		t.Fatal("keyring without primary key reported configured")
	}
	if _, _, err := New(nil, 0).Seal("x"); err == nil {
		t.Fatal("Seal without a primary key must fail")
	}
}
